package lower

import "testing"

// A throwaway probe (#3sdynvn step 3): GetSymbolAtLocation answers a shorthand name's property, not the
// variable { x } reads or ({ x } = other) writes, so a walk matching names by l.symbol misses both. Each
// row is one walk's shorthand form, and each _control row the same program's plain form, which the walk
// sees. Each logs its stop or, where it lowers, Node's output beside native's.
func TestShorthandAuditProbe(t *testing.T) {
	t.Parallel()
	for _, probe := range []struct{ name, source string }{
		{"census_return_proof", "const other: { x: number } = { x: 7 };\nfunction pick(x: 1): 1;\nfunction pick(x: number): number {\n    ({ x } = other);\n    return x;\n}\nconst one: 1 = pick(1);\nconsole.log(`${one === 1 ? \"one\" : \"other\"} ${one + 1}`);\n"},
		{"census_return_proof_control", "const other: { x: number } = { x: 7 };\nfunction pick(x: 1): 1;\nfunction pick(x: number): number {\n    x = other.x;\n    return x;\n}\nconst one: 1 = pick(1);\nconsole.log(`${one === 1 ? \"one\" : \"other\"} ${one + 1}`);\n"},
		{"overload_callback_argument", "interface N { readonly kind: number }\ninterface Id extends N { readonly kind: 1; readonly text: string }\nfunction check(ok: unknown, m: string): void { if (!ok) { throw new Error(m); } }\nconst other: { node: N | undefined } = { node: { kind: 2 } };\nfunction assertNode<T extends N, U extends T>(node: T | undefined, test: (node: T) => node is U, message?: string): asserts node is U;\nfunction assertNode(node: N | undefined, test: ((node: N) => boolean) | undefined, message?: string): void;\nfunction assertNode(node: N | undefined, test: ((node: N) => boolean) | undefined, message?: string): void {\n    ({ node } = other);\n    check(node !== undefined && (test === undefined || test(node)), message || \"Unexpected node.\");\n}\nconst id: Id = { kind: 1, text: \"a\" };\nassertNode(id, (x: Id): x is Id => x.text === \"a\");\nconsole.log(id.text);\n"},
		{"overload_callback_argument_control", "interface N { readonly kind: number }\ninterface Id extends N { readonly kind: 1; readonly text: string }\nfunction check(ok: unknown, m: string): void { if (!ok) { throw new Error(m); } }\nconst other: { node: N | undefined } = { node: { kind: 2 } };\nfunction assertNode<T extends N, U extends T>(node: T | undefined, test: (node: T) => node is U, message?: string): asserts node is U;\nfunction assertNode(node: N | undefined, test: ((node: N) => boolean) | undefined, message?: string): void;\nfunction assertNode(node: N | undefined, test: ((node: N) => boolean) | undefined, message?: string): void {\n    node = other.node;\n    check(node !== undefined && (test === undefined || test(node)), message || \"Unexpected node.\");\n}\nconst id: Id = { kind: 1, text: \"a\" };\nassertNode(id, (x: Id): x is Id => x.text === \"a\");\nconsole.log(id.text);\n"},
		{"predicate_overload_callback", "interface Circle { readonly kind: \"circle\"; readonly radius: number }\ninterface Square { readonly kind: \"square\"; readonly side: number }\ntype Shape = Circle | Square;\nconst liar: { predicate: (element: Shape) => boolean } = { predicate: (element: Shape) => element.kind === \"square\" };\nfunction first(array: readonly Shape[], predicate: (element: Shape) => element is Circle): Circle | undefined;\nfunction first(array: readonly Shape[], predicate: (element: Shape) => boolean): Shape | undefined;\nfunction first(array: readonly Shape[], predicate: (element: Shape) => boolean): Shape | undefined {\n    ({ predicate } = liar);\n    for (const value of array) {\n        if (predicate(value)) {\n            return value;\n        }\n    }\n    return undefined;\n}\nconst shapes: Shape[] = [{ kind: \"square\", side: 2 }, { kind: \"circle\", radius: 3 }];\nconst circle = first(shapes, (x): x is Circle => x.kind === \"circle\");\nconsole.log(circle === undefined ? \"none\" : `radius ${circle.radius}`);\n"},
		{"predicate_overload_callback_control", "interface Circle { readonly kind: \"circle\"; readonly radius: number }\ninterface Square { readonly kind: \"square\"; readonly side: number }\ntype Shape = Circle | Square;\nconst liar: { predicate: (element: Shape) => boolean } = { predicate: (element: Shape) => element.kind === \"square\" };\nfunction first(array: readonly Shape[], predicate: (element: Shape) => element is Circle): Circle | undefined;\nfunction first(array: readonly Shape[], predicate: (element: Shape) => boolean): Shape | undefined;\nfunction first(array: readonly Shape[], predicate: (element: Shape) => boolean): Shape | undefined {\n    predicate = liar.predicate;\n    for (const value of array) {\n        if (predicate(value)) {\n            return value;\n        }\n    }\n    return undefined;\n}\nconst shapes: Shape[] = [{ kind: \"square\", side: 2 }, { kind: \"circle\", radius: 3 }];\nconst circle = first(shapes, (x): x is Circle => x.kind === \"circle\");\nconsole.log(circle === undefined ? \"none\" : `radius ${circle.radius}`);\n"},
		{"predicate_overload_binding", "interface Circle { readonly kind: \"circle\"; readonly radius: number }\ninterface Square { readonly kind: \"square\"; readonly side: number }\ntype Shape = Circle | Square;\nlet hook: () => void = () => {};\nconst other: { node: Shape } = { node: { kind: \"square\", side: 2 } };\nfunction findIt(node: Shape, callback: (element: Shape) => element is Circle): Circle | undefined;\nfunction findIt(node: Shape, callback: (element: Shape) => boolean): Shape | undefined;\nfunction findIt(node: Shape, callback: (element: Shape) => boolean): Shape | undefined {\n    hook = () => { ({ node } = other); };\n    const result = callback(node);\n    if (result) {\n        return node;\n    }\n    return undefined;\n}\nconst found = findIt({ kind: \"circle\", radius: 3 }, (x): x is Circle => { hook(); return x.kind === \"circle\"; });\nconsole.log(found === undefined ? \"none\" : `radius ${found.radius}`);\n"},
		{"predicate_overload_binding_control", "interface Circle { readonly kind: \"circle\"; readonly radius: number }\ninterface Square { readonly kind: \"square\"; readonly side: number }\ntype Shape = Circle | Square;\nlet hook: () => void = () => {};\nconst other: { node: Shape } = { node: { kind: \"square\", side: 2 } };\nfunction findIt(node: Shape, callback: (element: Shape) => element is Circle): Circle | undefined;\nfunction findIt(node: Shape, callback: (element: Shape) => boolean): Shape | undefined;\nfunction findIt(node: Shape, callback: (element: Shape) => boolean): Shape | undefined {\n    hook = () => { node = other.node; };\n    const result = callback(node);\n    if (result) {\n        return node;\n    }\n    return undefined;\n}\nconst found = findIt({ kind: \"circle\", radius: 3 }, (x): x is Circle => { hook(); return x.kind === \"circle\"; });\nconsole.log(found === undefined ? \"none\" : `radius ${found.radius}`);\n"},
		{"overload_default_absent", "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nconst other: { comparer: undefined } = { comparer: undefined };\nfunction sortAndDeduplicate(array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\t({ comparer } = other);\n\treturn dedupeSorted(sortWith(array, comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate(['b', 'a', 'c', 'a']).join(','));\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\n"},
		{"overload_default_absent_control", "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nconst other: { comparer: undefined } = { comparer: undefined };\nfunction sortAndDeduplicate(array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\tcomparer = other.comparer;\n\treturn dedupeSorted(sortWith(array, comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate(['b', 'a', 'c', 'a']).join(','));\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\n"},
		{"overload_default_only_called", "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nconst other: { comparer: undefined } = { comparer: undefined };\nfunction sortAndDeduplicate(array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\treturn dedupeSorted(sortWith(array, comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate(['b', 'a', 'c', 'a']).join(','));\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\nconst holder = { sortAndDeduplicate };\nconsole.log(holder.sortAndDeduplicate(['b', 'a']).join(','));\n"},
		{"overload_default_only_called_control", "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nconst other: { comparer: undefined } = { comparer: undefined };\nfunction sortAndDeduplicate(array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\treturn dedupeSorted(sortWith(array, comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate(['b', 'a', 'c', 'a']).join(','));\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\nconst holder = { sortAndDeduplicate: sortAndDeduplicate };\nconsole.log(holder.sortAndDeduplicate(['b', 'a']).join(','));\n"},
		{"flow_predicate_parameter", "const other: { x: string | number } = { x: 7 };\nfunction isNumber(x: string | number): x is number {\n    ({ x } = other);\n    return typeof x === \"number\";\n}\nfunction show(v: string | number): string {\n    if (isNumber(v)) {\n        return `number ${v + 1}`;\n    }\n    return \"other\";\n}\nconsole.log(show(\"text\"));\n"},
		{"flow_predicate_parameter_control", "const other: { x: string | number } = { x: 7 };\nfunction isNumber(x: string | number): x is number {\n    x = other.x;\n    return typeof x === \"number\";\n}\nfunction show(v: string | number): string {\n    if (isNumber(v)) {\n        return `number ${v + 1}`;\n    }\n    return \"other\";\n}\nconsole.log(show(\"text\"));\n"},
		{"predicate_overload_proven", "const other: { x: string | number } = { x: 7 };\nfunction isNumber(x: string | number): x is number;\nfunction isNumber(x: string | number): boolean {\n    ({ x } = other);\n    return typeof x === \"number\";\n}\nfunction show(v: string | number): string {\n    if (isNumber(v)) {\n        return `number ${v + 1}`;\n    }\n    return \"other\";\n}\nconsole.log(show(\"text\"));\n"},
		{"predicate_overload_proven_control", "const other: { x: string | number } = { x: 7 };\nfunction isNumber(x: string | number): x is number;\nfunction isNumber(x: string | number): boolean {\n    x = other.x;\n    return typeof x === \"number\";\n}\nfunction show(v: string | number): string {\n    if (isNumber(v)) {\n        return `number ${v + 1}`;\n    }\n    return \"other\";\n}\nconsole.log(show(\"text\"));\n"},
		{"checked_predicate_closure", "const other: { x: string | number } = { x: 7 };\nconst isNumber = (x: string | number): x is number => {\n    ({ x } = other);\n    return true;\n};\nfunction show(v: string | number): string {\n    if (isNumber(v)) {\n        return `number ${v + 1}`;\n    }\n    return \"other\";\n}\nconsole.log(show(\"text\"));\n"},
		{"checked_predicate_closure_control", "const other: { x: string | number } = { x: 7 };\nconst isNumber = (x: string | number): x is number => {\n    x = other.x;\n    return true;\n};\nfunction show(v: string | number): string {\n    if (isNumber(v)) {\n        return `number ${v + 1}`;\n    }\n    return \"other\";\n}\nconsole.log(show(\"text\"));\n"},
		{"inferred_predicate", "const other: { x: string | number } = { x: 7 };\nfunction keep(values: (string | number)[], test: (v: string | number) => v is number): number[] {\n    const out: number[] = [];\n    for (const v of values) {\n        if (test(v)) {\n            out.push(v);\n        }\n    }\n    return out;\n}\nconst kept = keep([\"text\"], (x) => { ({ x } = other); return typeof x === \"number\"; });\nconsole.log(`${kept.length} ${kept.length > 0 ? kept[0]! + 1 : 0}`);\n"},
		{"inferred_predicate_control", "const other: { x: string | number } = { x: 7 };\nfunction keep(values: (string | number)[], test: (v: string | number) => v is number): number[] {\n    const out: number[] = [];\n    for (const v of values) {\n        if (test(v)) {\n            out.push(v);\n        }\n    }\n    return out;\n}\nconst kept = keep([\"text\"], (x) => { x = other.x; return typeof x === \"number\"; });\nconsole.log(`${kept.length} ${kept.length > 0 ? kept[0]! + 1 : 0}`);\n"},
		{"enumeration_binding", "const wide = { a: 1, b: 2, c: \"x\" };\nconst other: { held: { a: number; b: number } } = { held: wide };\nlet held = { a: 4, b: 5 };\n({ held } = other);\nconst values = Object.values(held);\nconsole.log(`${values.length} ${values.join(\",\")}`);\n"},
		{"enumeration_binding_control", "const wide = { a: 1, b: 2, c: \"x\" };\nconst other: { held: { a: number; b: number } } = { held: wide };\nlet held = { a: 4, b: 5 };\nheld = other.held;\nconst values = Object.values(held);\nconsole.log(`${values.length} ${values.join(\",\")}`);\n"},
		{"evolving_object", "function run(): string {\n    let v;\n    v = { size: 1 };\n    const first = `${v.size}`;\n    ({ v } = other);\n    return `${first} ${v.name}`;\n}\nconst other = { v: { name: \"b\" } };\nconsole.log(run());\n"},
		{"evolving_object_control", "function run(): string {\n    let v;\n    v = { size: 1 };\n    const first = `${v.size}`;\n    v = other.v;\n    return `${first} ${v.name}`;\n}\nconst other = { v: { name: \"b\" } };\nconsole.log(run());\n"},
		{"plain_enumerable_for_in", "const wide = { a: 1, b: 2, c: 3 };\nconst other: { obj: { a: number; b: number } } = { obj: wide };\nlet obj = { a: 4, b: 5 };\n({ obj } = other);\nlet keys = \"\";\nfor (const key in obj) {\n    keys += key;\n}\nconsole.log(`${keys}`);\n"},
		{"plain_enumerable_for_in_control", "const wide = { a: 1, b: 2, c: 3 };\nconst other: { obj: { a: number; b: number } } = { obj: wide };\nlet obj = { a: 4, b: 5 };\nobj = other.obj;\nlet keys = \"\";\nfor (const key in obj) {\n    keys += key;\n}\nconsole.log(`${keys}`);\n"},
		{"record_read_discarded", "const dict: Record<string, number> = { a: 1 };\nconst v = dict[\"toString\"];\nconst held = { v };\nconsole.log(`${typeof held.v}`);\n"},
		{"record_read_discarded_control", "const dict: Record<string, number> = { a: 1 };\nconst v = dict[\"toString\"];\nconst held = { v: v };\nconsole.log(`${typeof held.v}`);\n"},
		{"static_class_escape", "class Box {\n    static first: number = Box.peek();\n    static second: number = 7;\n    static peek(): number {\n        const held = { Box };\n        return held.Box.second;\n    }\n}\nconsole.log(`${Box.first}`);\n"},
		{"static_class_escape_control", "class Box {\n    static first: number = Box.peek();\n    static second: number = 7;\n    static peek(): number {\n        const held = { Box: Box };\n        return held.Box.second;\n    }\n}\nconsole.log(`${Box.first}`);\n"},
		{"static_outside_helper", "function peek(): number {\n    const held = { Box };\n    return held.Box.second;\n}\nclass Box {\n    static first: number = peek();\n    static second: number = 7;\n}\nconsole.log(`${Box.first}`);\n"},
		{"static_outside_helper_control", "function peek(): number {\n    const held = { Box: Box };\n    return held.Box.second;\n}\nclass Box {\n    static first: number = peek();\n    static second: number = 7;\n}\nconsole.log(`${Box.first}`);\n"},
		{"static_judged_parameter", "const other = { fn: (): number => Box.second };\nfunction run(fn: () => number): number {\n    ({ fn } = other);\n    return fn();\n}\nclass Box {\n    static first: number = run(() => 1);\n    static second: number = 7;\n}\nconsole.log(`${Box.first}`);\n"},
		{"static_judged_parameter_control", "const other = { fn: (): number => Box.second };\nfunction run(fn: () => number): number {\n    fn = other.fn;\n    return fn();\n}\nclass Box {\n    static first: number = run(() => 1);\n    static second: number = 7;\n}\nconsole.log(`${Box.first}`);\n"},
		{"bind_receiver_parameter", "class Counter {\n    count = 1;\n    read(): number { return this.count; }\n}\nconst other = { counter: new Counter() };\nfunction bound(counter: Counter): () => number {\n    ({ counter } = other);\n    return counter.read.bind(counter);\n}\nconsole.log(`${bound(new Counter())()}`);\n"},
		{"bind_receiver_parameter_control", "class Counter {\n    count = 1;\n    read(): number { return this.count; }\n}\nconst other = { counter: new Counter() };\nfunction bound(counter: Counter): () => number {\n    counter = other.counter;\n    return counter.read.bind(counter);\n}\nconsole.log(`${bound(new Counter())()}`);\n"},
	} {
		t.Run(probe.name, func(t *testing.T) {
			t.Parallel()
			program, err := lowerSourceAs(t, probe.source, ".ts")
			if err != nil {
				t.Logf("ROW %s stops: %v", probe.name, err)
				return
			}
			node := runAgreementNode(t, writeAgreementSource(t, "main.ts", probe.source))
			code, stdout, stderr := brandedNative(t, program)
			t.Logf("ROW %s LOWERS: node exit %d %q; native exit %d %q stderr %q", probe.name, node.code, node.stdout, code, stdout, stderr)
		})
	}
}
